-- Celeta MVP — database schema v2.0
-- MySQL 8.0.16+
-- IDs are UUID v4 generated by the Node.js backend (crypto.randomUUID()).
-- Configure the MySQL server/session timezone as UTC.

CREATE DATABASE IF NOT EXISTS celeta_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

USE celeta_db;

CREATE TABLE users (
  id CHAR(36) NOT NULL,
  email VARCHAR(255) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(16) NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_users PRIMARY KEY (id),
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT chk_users_role CHECK (role IN ('CANDIDATE', 'EMPLOYER'))
) ENGINE=InnoDB;

CREATE TABLE candidate_profiles (
  id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  full_name VARCHAR(150) NOT NULL,
  phone VARCHAR(30) NULL,
  professional_area VARCHAR(120) NULL,
  skills_json JSON NULL,
  career_objectives TEXT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_candidate_profiles PRIMARY KEY (id),
  CONSTRAINT uq_candidate_profiles_user UNIQUE (user_id),
  CONSTRAINT fk_candidate_profiles_user FOREIGN KEY (user_id)
    REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE employer_profiles (
  id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  company_name VARCHAR(150) NOT NULL,
  cnpj CHAR(14) NULL,
  description TEXT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_employer_profiles PRIMARY KEY (id),
  CONSTRAINT uq_employer_profiles_user UNIQUE (user_id),
  CONSTRAINT uq_employer_profiles_cnpj UNIQUE (cnpj),
  CONSTRAINT fk_employer_profiles_user FOREIGN KEY (user_id)
    REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE jobs (
  id CHAR(36) NOT NULL,
  employer_profile_id CHAR(36) NOT NULL,
  title VARCHAR(150) NOT NULL,
  description TEXT NOT NULL,
  requirements_json JSON NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',
  criteria_confirmed_at DATETIME(3) NULL,
  criteria_confirmed_by_user_id CHAR(36) NULL,
  published_at DATETIME(3) NULL,
  closed_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_jobs PRIMARY KEY (id),
  CONSTRAINT fk_jobs_employer_profile FOREIGN KEY (employer_profile_id)
    REFERENCES employer_profiles(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_jobs_criteria_confirmer FOREIGN KEY (criteria_confirmed_by_user_id)
    REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_jobs_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'CLOSED')),
  CONSTRAINT chk_jobs_criteria_confirmation CHECK (
    (criteria_confirmed_at IS NULL AND criteria_confirmed_by_user_id IS NULL)
    OR
    (criteria_confirmed_at IS NOT NULL AND criteria_confirmed_by_user_id IS NOT NULL)
  ),
  CONSTRAINT chk_jobs_published_requires_confirmation CHECK (
    status <> 'PUBLISHED' OR criteria_confirmed_at IS NOT NULL
  ),
  KEY idx_jobs_employer_status (employer_profile_id, status),
  FULLTEXT KEY ft_jobs_search (title, description)
) ENGINE=InnoDB;

CREATE TABLE job_criteria (
  id CHAR(36) NOT NULL,
  job_id CHAR(36) NOT NULL,
  name VARCHAR(150) NOT NULL,
  details TEXT NULL,
  criterion_type VARCHAR(12) NOT NULL,
  weight DECIMAL(5,2) NOT NULL DEFAULT 1.00,
  sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_job_criteria PRIMARY KEY (id),
  CONSTRAINT uq_job_criteria_id_job UNIQUE (id, job_id),
  CONSTRAINT fk_job_criteria_job FOREIGN KEY (job_id)
    REFERENCES jobs(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_job_criteria_type CHECK (criterion_type IN ('REQUIRED', 'DESIRABLE')),
  CONSTRAINT chk_job_criteria_weight CHECK (weight > 0 AND weight <= 10),
  KEY idx_job_criteria_job (job_id, sort_order)
) ENGINE=InnoDB;

CREATE TABLE resumes (
  id CHAR(36) NOT NULL,
  candidate_profile_id CHAR(36) NOT NULL,
  title VARCHAR(100) NOT NULL,
  storage_key VARCHAR(500) NOT NULL,
  file_size_bytes INT UNSIGNED NOT NULL,
  extracted_text LONGTEXT NULL,
  extraction_status VARCHAR(12) NOT NULL DEFAULT 'PENDING',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_resumes PRIMARY KEY (id),
  CONSTRAINT uq_resumes_storage_key UNIQUE (storage_key),
  CONSTRAINT uq_resumes_id_candidate UNIQUE (id, candidate_profile_id),
  CONSTRAINT fk_resumes_candidate_profile FOREIGN KEY (candidate_profile_id)
    REFERENCES candidate_profiles(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_resumes_extraction_status CHECK (
    extraction_status IN ('PENDING', 'COMPLETED', 'FAILED')
  ),
  KEY idx_resumes_candidate (candidate_profile_id, created_at)
) ENGINE=InnoDB;

CREATE TABLE applications (
  id CHAR(36) NOT NULL,
  job_id CHAR(36) NOT NULL,
  candidate_profile_id CHAR(36) NOT NULL,
  resume_id CHAR(36) NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'IN_REVIEW',
  selection_phase VARCHAR(12) NOT NULL DEFAULT 'BLIND',
  screening_status VARCHAR(12) NOT NULL DEFAULT 'PENDING',
  ai_classification VARCHAR(16) NULL,
  compatibility_score DECIMAL(5,2) NULL,
  ai_summary TEXT NULL,
  screening_started_at DATETIME(3) NULL,
  screening_completed_at DATETIME(3) NULL,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_applications PRIMARY KEY (id),
  CONSTRAINT uq_applications_job_candidate UNIQUE (job_id, candidate_profile_id),
  CONSTRAINT uq_applications_id_job UNIQUE (id, job_id),
  CONSTRAINT fk_applications_job FOREIGN KEY (job_id)
    REFERENCES jobs(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_applications_resume_owner FOREIGN KEY (resume_id, candidate_profile_id)
    REFERENCES resumes(id, candidate_profile_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_applications_status CHECK (
    status IN ('IN_REVIEW', 'ADVANCED', 'NOT_SELECTED')
  ),
  CONSTRAINT chk_applications_selection_phase CHECK (
    selection_phase IN ('BLIND', 'IDENTIFIED')
  ),
  CONSTRAINT chk_applications_screening_status CHECK (
    screening_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED')
  ),
  CONSTRAINT chk_applications_ai_classification CHECK (
    ai_classification IS NULL
    OR ai_classification IN ('ELIGIBLE', 'NOT_ELIGIBLE', 'REVIEW_REQUIRED')
  ),
  CONSTRAINT chk_applications_score CHECK (
    compatibility_score IS NULL
    OR (compatibility_score >= 0 AND compatibility_score <= 100)
  ),
  KEY idx_applications_job_status_score (job_id, status, compatibility_score),
  KEY idx_applications_candidate_date (candidate_profile_id, applied_at)
) ENGINE=InnoDB;

CREATE TABLE application_criterion_evaluations (
  id CHAR(36) NOT NULL,
  application_id CHAR(36) NOT NULL,
  job_id CHAR(36) NOT NULL,
  criterion_id CHAR(36) NOT NULL,
  result VARCHAR(24) NOT NULL,
  evidence_text TEXT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
    ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_application_criterion_evaluations PRIMARY KEY (id),
  CONSTRAINT uq_application_criterion UNIQUE (application_id, criterion_id),
  CONSTRAINT fk_evaluations_application_job FOREIGN KEY (application_id, job_id)
    REFERENCES applications(id, job_id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_evaluations_criterion_job FOREIGN KEY (criterion_id, job_id)
    REFERENCES job_criteria(id, job_id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_evaluations_result CHECK (
    result IN ('MET', 'NOT_MET', 'INSUFFICIENT_EVIDENCE')
  ),
  KEY idx_evaluations_criterion_job (criterion_id, job_id)
) ENGINE=InnoDB;

CREATE TABLE auth_sessions (
  id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  token_hash CHAR(64) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  last_used_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT pk_auth_sessions PRIMARY KEY (id),
  CONSTRAINT uq_auth_sessions_token_hash UNIQUE (token_hash),
  CONSTRAINT fk_auth_sessions_user FOREIGN KEY (user_id)
    REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE,
  KEY idx_auth_sessions_user (user_id),
  KEY idx_auth_sessions_expiration (expires_at)
) ENGINE=InnoDB;
